def icon(n): return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">{ICONS[n]}</svg>'
def btn(label,to,kind=''): return f'<a class="button {kind}" href="{to}.html">{label}</a>'
def row(title,sub='',end='',to=None,ic=None):
    content=f'{icon(ic) if ic else ""}<span class="grow"><strong>{title}</strong>{f"<span class=small>{sub}</span>" if sub else ""}</span><span class="end">{end}</span>{icon("next") if to else ""}'
    return f'<a class="row" href="{to}.html">{content}</a>' if to else f'<div class="row">{content}</div>'
def nav(sel='home'):
    return '<nav class="nav" aria-label="Main">'+''.join(f'<a class="{"selected" if k==sel else ""}" href="{to}.html">{icon(k)}{label}</a>' for k,label,to in [('home','Lock','08-home-ready'),('stats','Stats','24-stats'),('settings','Settings','29-settings')])+'</nav>'
def top(title='',back=None,right=None):
    return f'<header class="top">{f"<a href={back}.html aria-label=Back>{icon("back")}</a>" if back else "<span></span>"}<strong>{title}</strong>{right or "<span></span>"}</header>'
def mark(n='lock'):return f'<div class="mark">{icon(n)}</div>'
def heading(a,b=''):return f'<h1>{a}</h1>{f"<p>{b}</p>" if b else ""}'
def note(s):return f'<div class="note">{s}</div>'
PAGES=[]
def page(slug,title,body,bottom='',tabs=None,header='',overlay='',section=''):
    PAGES.append(dict(slug=slug,title=title,section=section))
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>{title} · Blocker design</title><style>{CSS}</style></head><body><main class="phone"><div class="status" aria-hidden="true"><span>9:41</span><svg viewBox="0 0 64 16" fill="currentColor"><path d="M1 12h3v3H1zm5-3h3v6H6zm5-3h3v9h-3zm5-3h3v12h-3zM24 5q8-7 16 0l-2 2q-6-5-12 0zm4 4q4-4 8 0l-2 2q-2-2-4 0zm3 4 1-1 1 1-1 1z"/><rect x="45" y="3" width="15" height="10" rx="2" fill="none" stroke="currentColor"/><rect x="47" y="5" width="11" height="6" rx="1"/><path d="M62 6h2v4h-2z"/></svg></div>{header}<section class="content">{body}</section>{f'<footer class="bottom">{bottom}</footer>' if bottom else ''}{nav(tabs) if tabs else ''}{overlay}<div class="homebar" aria-hidden="true"></div></main></body></html>'''
    (ROOT/f'{slug}.html').write_text(doc)

