INDEX_CSS=''' :root{--bg:#000;--surface:#141414;--text:#fafafa;--muted:#aaa;--line:#333;--font:-apple-system,BlinkMacSystemFont,"Helvetica Neue",sans-serif}*{box-sizing:border-box}html,body{overflow-x:clip}body{background:var(--bg);color:var(--text);font-family:var(--font);margin:0;padding:56px 32px}main{max-width:1480px;margin:auto}h1{font-size:44px;letter-spacing:-1.5px;margin:0 0 12px}p{color:var(--muted);line-height:1.6;max-width:760px}h2{font-size:26px;margin:56px 0 24px}a{color:inherit}a:focus-visible{outline:2px solid var(--text);outline-offset:6px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:32px 24px}figure{margin:0;min-width:0}img{width:100%;height:auto;border:1px solid var(--line);border-radius:24px;display:block}figcaption{padding:14px 0;font-size:14px;line-height:1.5}small{display:block;color:var(--muted);margin-top:4px}nav{display:flex;flex-wrap:wrap;gap:20px;margin-top:28px}footer{margin-top:64px;color:var(--muted)}'''
sections=list(dict.fromkeys(p['section'] for p in PAGES))
index='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Blocker · V1 design review</title><style>'+INDEX_CSS+'</style></head><body><main><h1>A little distance.</h1><p>Blocker / V1 screen designs / APP-11</p><p>Black, white and graphite. One group. One length. One deliberate commitment. These are offline design mockups, not app code. All usage is synthetic.</p><p>Apple owns permission, picker and shield layouts; those screens are illustrative. Shield time remaining is a snapshot. Attempts are unavailable; time saved is an estimate. <a href="DESIGN.md">Read the design and platform limits</a>.</p><nav>'+''.join(f'<a href="#{s.replace(" ","-")}">{s}</a>' for s in sections)+'</nav>'
for section in sections:
    index+=f'<section id="{section.replace(" ","-")}"><h2>{section}</h2><div class="grid">'
    for p in PAGES:
        if p['section']==section:
            index+=f'<figure><a href="{p["slug"]}.html"><img src="screenshots/{p["slug"]}.png" width="402" height="874" loading="lazy" alt="{p["title"]}"></a><figcaption>{p["title"]}<small><a href="{p["slug"]}.html">HTML</a> / <a href="screenshots/{p["slug"]}.png">PNG</a></small></figcaption></figure>'
    index+='</div></section>'
index+='<footer>Design only. iOS 27 target. Review the commitment and API caveats before implementation.</footer></main></body></html>'
(ROOT/'index.html').write_text(index)
print(f'Generated {len(PAGES)} self-contained screen mockups and contact sheet.')
